#!/bin/bash
set -euo pipefail
workspace=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
extra='-DCMAKE_C_COMPILER=/usr/bin/gcc-14 -DCMAKE_CXX_COMPILER=/usr/bin/g++-14 -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DMYSQL_MAINTAINER_MODE=OFF -DDEB_NOROUTER=1 -DWITH_ROUTER=OFF -DDEB_ID=debian -DDEB_RELEASE=14 -DDEB_CODENAME=forky -DWITH_SYSTEMD=ON -DWITH_AUTHENTICATION_CLIENT_PLUGINS=ON -DWITH_FIDO=system -DWITH_KERBEROS=system'
cmake -S "$workspace/src/mysql-8.4.0" -B "$workspace/deb-config"  -DBUILD_CONFIG=mysql_release  -DCMAKE_C_COMPILER=/usr/bin/gcc-14  -DCMAKE_CXX_COMPILER=/usr/bin/g++-14  -DCMAKE_POLICY_VERSION_MINIMUM=3.5  -DMYSQL_MAINTAINER_MODE=OFF  -DCMAKE_INSTALL_PREFIX=/usr  -DINSTALL_LIBDIR=lib/loongarch64-linux-gnu  -DSYSCONFDIR=/etc/mysql  -DMYSQL_UNIX_ADDR=/var/run/mysqld/mysqld.sock  -DINSTALL_LAYOUT=DEB  -DDEB_PRODUCT=community  -DDEB_ID=debian -DDEB_RELEASE=14 -DDEB_CODENAME=forky  -DDEB_NOROUTER=1 -DWITH_ROUTER=OFF  -DWITH_MECAB=system -DWITH_NUMA=ON -DWITH_SYSTEMD=ON -DWITH_AUTHENTICATION_CLIENT_PLUGINS=ON -DWITH_FIDO=system -DWITH_KERBEROS=system  -DDEB_CMAKE_EXTRAS="$extra"
